function parseFlags(args) {
    const result = { _: [] };
    for (const arg of args) {
        if (arg.startsWith("--")) {
            const [key, value = "true"] = arg.slice(2).split("=");
            result[key] = value;
        } else {
            result._.push(arg);
        }
    }
    return result;
}

