function addDependency(pkg, name, version, { dev = false } = {}) {
    const field = dev ? "devDependencies" : "dependencies";
    const next = { ...pkg, [field]: { ...pkg[field], [name]: `^${version}` } };
    next[field] = Object.fromEntries(
        Object.entries(next[field]).sort(([a], [b]) => a.localeCompare(b)),
    );
    return next;
}

let pkg = { name: "kod-retsept", version: "1.0.0" };
pkg = addDependency(pkg, "picocolors", "1.1.1");
pkg = addDependency(pkg, "express", "5.1.0");
pkg = addDependency(pkg, "prettier", "3.3.0", { dev: true });
console.log(JSON.stringify(pkg, null, 2));

const installed = { react: "19.1.0", "react-dom": "18.3.1" };
const peers = { react: ">=18", "react-dom": ">=19", "react-router": ">=7" };

for (const [name, range] of Object.entries(peers)) {
    const have = installed[name];
    if (!have) {
        console.log(`${name}: o'rnatilmagan, kerak ${range}`);
        continue;
    }
    const need = Number(range.replace(">=", ""));
    const ok = Number(have.split(".")[0]) >= need;
    console.log(`${name}@${have}: ${ok ? "mos" : "mos emas, kerak " + range}`);
}

const SEMVER = /^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?(?:\+([0-9A-Za-z.-]+))?$/;

function parse(version) {
    const m = SEMVER.exec(version);
    if (!m) throw new TypeError(`Noto'g'ri versiya: ${version}`);
    return { major: +m[1], minor: +m[2], patch: +m[3], prerelease: m[4]?.split(".") ?? [], build: m[5] ?? null };
}

console.log(parse("1.2.3"));
console.log(parse("2.0.0-beta.1+build.5"));
for (const bad of ["1.2", "v1.2.3"]) {
    try {
