const isNum = (s) => /^\d+$/.test(s);

function parse(version) {
    const dash = version.indexOf("-");
    const core = (dash === -1 ? version : version.slice(0, dash)).split(".").map(Number);
    return { core, pre: dash === -1 ? [] : version.slice(dash + 1).split(".") };
}

function comparePre(a, b) {
    if (!a.length || !b.length) return b.length - a.length;
    for (let i = 0; i < Math.max(a.length, b.length); i++) {
        const [x, y] = [a[i], b[i]];
        if (x === undefined) return -1;
        if (y === undefined) return 1;
        if (x === y) continue;
        if (isNum(x) && isNum(y)) return Number(x) - Number(y);
        if (isNum(x) !== isNum(y)) return isNum(x) ? -1 : 1;
        return x < y ? -1 : 1;
    }
    return 0;
}

function compare(v1, v2) {
    const [a, b] = [parse(v1), parse(v2)];
    return a.core[0] - b.core[0] || a.core[1] - b.core[1] || a.core[2] - b.core[2] || comparePre(a.pre, b.pre);
}

