console.log([...list].sort());
console.log([...list].sort(compare));

function interval(range) {
    const op = range[0];
    const [major, minor = 0, patch = 0] = range.slice(1).split(".").map(Number);
    let high;
    if (op === "~") high = `${major}.${minor + 1}.0`;
    else if (major > 0) high = `${major + 1}.0.0`;
    else if (minor > 0) high = `0.${minor + 1}.0`;
    else high = `0.0.${patch + 1}`;
    return `>=${major}.${minor}.${patch} <${high}`;
}

for (const range of ["^1.2.3", "^0.2.3", "^0.0.3", "~1.2.3", "~1.2", "^1.2"]) {
    console.log(range.padEnd(8), "→", interval(range));
}

const cmp = (a, b) => a[0] - b[0] || a[1] - b[1] || a[2] - b[2];

function predicate(token) {
    const m = /^([\^~]|>=|<=|>|<|=)?(\d+|[x*])(?:\.(\d+|[x*]))?(?:\.(\d+|[x*]))?$/.exec(token);
    if (!m) throw new Error(`Tushunarsiz oraliq: ${token}`);
    const op = m[1] ?? "=";
    const [major, minor, patch] = m.slice(2).map((p) => (p === undefined || /[x*]/.test(p) ? null : Number(p)));
    if (major === null) return () => true;
    const low = [major, minor ?? 0, patch ?? 0];
    const nextMajor = [major + 1, 0, 0];
    const nextMinor = [major, (minor ?? 0) + 1, 0];
    const nextPart = patch !== null ? [major, low[1], patch + 1] : minor !== null ? nextMinor : nextMajor;
    const caretUp = major > 0 || minor === null ? nextMajor : minor > 0 || patch === null ? nextMinor : nextPart;
    const tildeUp = minor === null ? nextMajor : nextMinor;
    const rules = {
        "^": (v) => cmp(v, low) >= 0 && cmp(v, caretUp) < 0,
        "~": (v) => cmp(v, low) >= 0 && cmp(v, tildeUp) < 0,
        ">=": (v) => cmp(v, low) >= 0,
        ">": (v) => cmp(v, nextPart) >= 0,
        "<": (v) => cmp(v, low) < 0,
        "<=": (v) => cmp(v, nextPart) < 0,
        "=": (v) => cmp(v, low) >= 0 && cmp(v, nextPart) < 0,
    };
    return rules[op];
}

function satisfies(version, range) {
    if (version.includes("-") && !range.includes("-")) return false;
    const v = version.split("-")[0].split(".").map(Number);
    return range.split("||").some((set) => set.trim().split(/\s+/).every((t) => predicate(t)(v)));
}

