const newest = (name, range) => {
    const major = range.slice(1).split(".")[0];
    return Object.keys(registry[name])
        .filter((v) => v.split(".")[0] === major)
        .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }))
        .at(-1);
};

const hoisted = {};
const nested = [];
function install(name, range, parent) {
    const version = newest(name, range);
    if (!(name in hoisted)) hoisted[name] = version;
    else if (hoisted[name] !== version) nested.push(`${parent}/node_modules/${name} ${version}`);
    for (const [dep, depRange] of Object.entries(registry[name][version])) install(dep, depRange, name);
}

