async function hajm(papka) {
    let jami = 0;
    for (const y of await fs.readdir(papka, { withFileTypes: true })) {
        const yol = path.join(papka, y.name);
        jami += y.isDirectory() ? await hajm(yol) : (await fs.stat(yol)).size;
    }
    return jami;
}

