import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";

class JsonStore {
    #file;
    #data = {};

    constructor(file) {
        this.#file = file;
    }

    async load() {
        try {
            this.#data = JSON.parse(await fs.readFile(this.#file, "utf8"));
        } catch (err) {
            if (err.code !== "ENOENT") throw err;
        }
        return this;
    }

    get(kalit) {
        return this.#data[kalit];
    }

    async set(kalit, qiymat) {
        this.#data[kalit] = qiymat;
        const vaqtincha = `${this.#file}.tmp`;
        await fs.writeFile(vaqtincha, JSON.stringify(this.#data));
        await fs.rename(vaqtincha, this.#file);
    }
}

const dir = await fs.mkdtemp(path.join(os.tmpdir(), "demo-"));
try {
