async function daraxt(papka, old = "") {
    const yozuvlar = (await fs.readdir(papka, { withFileTypes: true }))
        .sort((x, y) => x.name.localeCompare(y.name));
    for (const [i, y] of yozuvlar.entries()) {
        const oxirgi = i === yozuvlar.length - 1;
        console.log(old + (oxirgi ? "└── " : "├── ") + y.name);
        if (y.isDirectory()) {
            await daraxt(path.join(papka, y.name), old + (oxirgi ? "    " : "│   "));
        }
    }
}

