import http from "node:http";

class Router {
    #routes = [];

    get(yol, handler) {
        this.#routes.push({ metod: "GET", pattern: new URLPattern({ pathname: yol }), handler });
        return this;
    }

    handle(req, res) {
        const { pathname } = new URL(req.url, "http://localhost");
        for (const r of this.#routes) {
            const m = r.metod === req.method && r.pattern.exec({ pathname });
            if (m) return r.handler(res, m.pathname.groups);
        }
        res.writeHead(404, { "Content-Type": "application/json" });
        res.end(JSON.stringify({ xato: "Topilmadi" }));
    }
}

const json = (res, data) => {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify(data));
};

