import { Readable, Transform } from "node:stream";

function satrlarga() {
    let qoldiq = "";
    return new Transform({
        readableObjectMode: true,
        transform(chunk, enc, cb) {
            const qismlar = (qoldiq + chunk).split("\n");
            qoldiq = qismlar.pop();   // tugallanmagan oxirgi qism
            for (const q of qismlar) this.push(q);
            cb();
        },
        flush(cb) {
            if (qoldiq) this.push(qoldiq);
            cb();
        },
    });
}

const manba = Readable.from(["ism,bal", "l\nAziz,80\nDil", "noza,95"]);
for await (const satr of manba.pipe(satrlarga())) {
    console.log(satr);
}

