import zlib from "node:zlib";

const asl = Buffer.from("Salom, dunyo! ".repeat(200));

const variantlar = {
    gzip: [zlib.gzipSync, zlib.gunzipSync],
    deflate: [zlib.deflateSync, zlib.inflateSync],
    brotli: [zlib.brotliCompressSync, zlib.brotliDecompressSync],
};

for (const [nom, [siq, och]] of Object.entries(variantlar)) {
    const siqilgan = siq(asl);
    console.log(nom.padEnd(8), siqilgan.length < asl.length, och(siqilgan).equals(asl));
}

