import { Readable, Writable } from "node:stream";
import { pipeline } from "node:stream/promises";

const ac = new AbortController();

async function* cheksiz() {
    let i = 0;
    while (true) yield i++;
}

let qabul = 0;
const yozuvchi = new Writable({
    objectMode: true,
    write(chunk, enc, cb) {
        qabul++;
        if (qabul === 3) ac.abort();
        cb();
    },
});

try {
    await pipeline(Readable.from(cheksiz()), yozuvchi, { signal: ac.signal });
} catch (err) {
    console.log(err.name);
}
console.log("qabul qilingan bo'laklar >= 3:", qabul >= 3);

