import { Readable, Transform, Writable } from "node:stream";
import { pipeline } from "node:stream/promises";

class Progress extends Transform {
    #bayt = 0;

    _transform(chunk, encoding, callback) {
        this.#bayt += chunk.length;
        this.emit("progress", this.#bayt);
        callback(null, chunk);
    }
}

const progress = new Progress();
progress.on("progress", (bayt) => console.log(`jami: ${bayt} bayt`));

await pipeline(
    Readable.from(["salom", " ", "dunyo", "!"]),
    progress,
    new Writable({ write: (chunk, enc, cb) => cb() }),
);

import { Readable, Writable } from "node:stream";
import { pipeline } from "node:stream/promises";

function* sonlar(n) {
    for (let i = 1; i <= n; i++) yield i;
}

let jami = 0;
let soni = 0;
await pipeline(
    Readable.from(sonlar(100000)),
    async function* (manba) {
        for await (const n of manba) {
            if (n % 7 === 0) yield n;
        }
    },
    new Writable({
        objectMode: true,
        write(n, enc, cb) {
            jami += n;
            soni++;
            cb();
        },
    }),
);
console.log(soni, jami);
